// Financial Accounting WAEC/NECO questions for Naija Exam Prep, batch 2. Original practice questions; options are written with the
// correct one first and shuffled at build time. Every figure is worked out in `check` and compared with option A.
const is = (q, value) => ({ ...q, check: q.o[0] === value });
// Naira with thousands commas, e.g. N(12500) === "₦12,500". Non-whole results give a string that never matches an option.
const N = (x) => {
  const r = Math.round(x);
  if (Math.abs(r - x) > 1e-6) return `not whole: ${x}`;
  return (r < 0 ? "-₦" : "₦") + String(Math.abs(r)).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
};
